#include <vector>
#include <list>
#include <iostream>
#include <numeric>

int main() {
    std::vector<int> v(5, 10); // Size 5
    std::list<double> l(3);
    std::iota(l.begin(), l.end(), 1.5);

    // Assigns the three doubles (1.5, 2.5, 3.5) to v,
    // converting them to integers (1, 2, 3).
    v.assign(l.begin(), l.end());

    std::cout << "Vector size: " << v.size() << std::endl; // Output: 3
    std::cout << v[0] << ", " << v[1] << ", " << v[2] << std::endl; 
}
